    raw = raw.strip()
    if raw and raw[0] in "\\"'":
        end = raw.find(raw[0], 1)
        if end != -1:
            return raw[1:end]
    # unquoted: strip trailing inline comment (" #...")
    for i, ch in enumerate(raw):
        if ch == "#" and i > 0 and raw[i - 1] in " \\t":
            return raw[:i].rstrip()
    return raw


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if line.startswith("export") and line[6:7] in (" ", "\\t"):
                line = line[6:].lstrip()
            if "=" not in line:
                continue
            key, value = line.split("=", 1)
            values[key.strip()] = _parse_value(value)
    return values


SECRETS = {"PAYHOOK_API_TOKEN", "PAYHOOK_WEBHOOK_SECRET"}


def mask(key, value):
    """Redact secrets so output is safe to paste into a support ticket."""
    if value is None or key not in SECRETS:
        return value
    return "<set, %d chars>" % len(value) if value else "<empty>"


